import catalog from '../../src/data/catalog.json';import variants from '../../src/data/report-variants.json';import samples from './measurements.json';import {makeDraft,recordBlank} from '../../src/domain/model.ts';import {defaultReportSettings} from '../../src/domain/reports.ts';import {ReportEngine} from '../../src/engine/client.ts';import {ReportGeneration} from '../../src/domain/report-generation.ts';import {ReportQueue} from '../../src/domain/report-queue.ts';import {isSoundExperiment} from '../../src/domain/sound-phase.ts';import {Repository} from '../../src/domain/repository.ts';import type {Experiment} from '../../src/domain/types.ts';
export async function verifyRealReportQueue(customQuiz=false){
 const exps=catalog.experiments as Experiment[],records=new Map(exps.map(e=>[e.id,{...recordBlank(e),draft:makeDraft(e.schema,(samples as any)[e.id]),...(isSoundExperiment(e)?{soundPhase:'alternating' as const}:{})}])),settings=new Map(exps.map(e=>[e.id,defaultReportSettings()])),store=new Map<string,string>(),repo=new Repository({read:async key=>store.get(key)??null,write:async(k,v)=>{store.set(k,v)},remove:async k=>{store.delete(k)}}),engine=new ReportEngine(async()=>null),stages=new Map<string,{bytes:number;formulas:number}>(),profile={name:'队列模拟测试',studentId:'TEST',className:'功能验证'};let calls=0,active=0,max=0;const marker='队列自定义答案验证';if(customQuiz)for(const value of settings.values())(value as any).customQuestions=['说明本实验原理'];
 const generator=new ReportGeneration({generate:async(job,progress)=>{calls++;active++;max=Math.max(max,active);try{return await engine.generate(job,progress);}finally{active--;}},cancel:()=>engine.cancel(),quiz:async()=>({quiz:{questions:['说明本实验原理'],answers:{'1':[marker]}},notices:[]}),photo:async()=>{throw Error('unexpected photo');},plot:async()=>{throw Error('unexpected plot');},stage:async(id,generation,result)=>{if(result.docx[0]!==80||result.docx[1]!==75||result.docx.length<1000)throw Error('DOCX invalid');if(customQuiz){const xml=await documentXml(result.docx);if(!xml.includes(marker))throw Error('自定义答案未写入 DOCX：'+id);}stages.set(generation,{bytes:result.docx.length,formulas:result.metadata.formulaCount});return result.charts.map((c,i)=>({name:c.name,file:'chart-'+(i+1)+'.png'}));},publish:(exp,report)=>repo.saveReport(exp,report),remove:async(_id,generation)=>{stages.delete(generation);},prune:async()=>{}});
 const snap=(id:string)=>({record:structuredClone(records.get(id)!),profile,photoPath:null,settings:structuredClone(settings.get(id)!)});records.set(exps[1].id,recordBlank(exps[1]));
 const queue=new ReportQueue(async(id,signal,progress,phase)=>{const exp=exps.find(e=>e.id===id)!;await generator.run({exp,snapshot:snap(id),templates:(variants as any)[id],photo:null,fresh:async()=>snap(id)},signal,progress,phase);},()=>{});
 await queue.start(exps);if(queue.items.some((i,index)=>i.status!==(index===1?'failed':'done'))||calls!==27||max!==1)throw Error('队列未隔离失败或非串行：'+JSON.stringify(queue.items.map(i=>({id:i.id,status:i.status,error:i.message}))));
 for(const exp of exps.filter((_,index)=>index!==1)){const saved=(await repo.loadReport(exp)).value;if(!saved||!stages.has(saved.generation))throw Error('报告未回读');}
 records.set(exps[1].id,{...recordBlank(exps[1]),draft:makeDraft(exps[1].schema,(samples as any)[exps[1].id])});await queue.retry();if(!queue.items.every(i=>i.status==='done')||calls!==28)throw Error('重试重复生成成功任务');
 const reports=[];for(const exp of exps){const saved=(await repo.loadReport(exp)).value!;reports.push({id:exp.id,name:exp.name,...stages.get(saved.generation)});}
 return {checks:['28 experiment queue serially generates 27 actual WASM reports and isolates incomplete data','generated DOCX metadata and generation identities read back through actual Repository','fixing incomplete data retries only the failed experiment with real report engine'],reports,maxConcurrent:max,calls,customQuiz};
}

async function documentXml(bytes:Uint8Array){
 const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let end=bytes.length-22;while(end>=0&&v.getUint32(end,true)!==0x06054b50)end--;if(end<0)throw Error('ZIP directory missing');let entry=v.getUint32(end+16,true);
 for(let i=0;i<v.getUint16(end+10,true);i++){if(v.getUint32(entry,true)!==0x02014b50)throw Error('ZIP entry missing');const nameSize=v.getUint16(entry+28,true),name=new TextDecoder().decode(bytes.slice(entry+46,entry+46+nameSize));if(name==='word/document.xml'){const offset=v.getUint32(entry+42,true),size=v.getUint32(entry+20,true),method=v.getUint16(entry+10,true),start=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true),data=bytes.slice(start,start+size);if(method===0)return new TextDecoder().decode(data);if(method!==8)throw Error('ZIP compression unknown');const decompressed=await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer();return new TextDecoder().decode(decompressed);}entry+=46+nameSize+v.getUint16(entry+30,true)+v.getUint16(entry+32,true);}throw Error('Document XML missing');
}
